// The Worker's entry point (wrangler.jsonc "main"): the OpenNext build of the
// app (.open-next/worker.js, written by `opennextjs-cloudflare build`), wrapped
// by Sentry (./sentry.ts). File-like paths that are not routes get a plain 404
// before Next (./missing-file.ts).
import * as Sentry from "@sentry/cloudflare";
// Generated by the build, so missing before one (ts-expect-error would then
// fail after one).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNext from "../.open-next/worker.js";
import { missingFile } from "./missing-file";
import { sentryOptions } from "./sentry";

type Handler = Parameters<typeof Sentry.withSentry>[1];
type Fetch = (request: Request, env: CloudflareEnv, ctx: unknown) => Promise<Response>;
const app = openNext as Handler & { fetch: Fetch };

const worker = {
  ...app,
  fetch(request: Request, env: CloudflareEnv, ctx: unknown) {
    return missingFile(request) ?? app.fetch(request, env, ctx);
  },
} as Handler;

export default Sentry.withSentry((env: CloudflareEnv) => sentryOptions(env), worker);
